import React, { useState, useEffect } from "react";
import { useStaticQuery, graphql } from "gatsby";

interface CompanyNode {
  name: string;
  publicURL: string;
}

const LogoMarquee: React.FC = () => {
  const data = useStaticQuery<{ allFile: { nodes: CompanyNode[] } }>(graphql`
    query CompanyLogos {
      allFile(
        filter: { sourceInstanceName: { eq: "companies" } }
        sort: { name: ASC }
      ) {
        nodes {
          name
          publicURL
        }
      }
    }
  `);

  const logos = data.allFile.nodes;
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [paused, setPaused] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(hover: none)");
    setIsMobile(mq.matches);
    const h = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mq.addEventListener("change", h);
    return () => mq.removeEventListener("change", h);
  }, []);

  const displayName = (raw: string) =>
    raw.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

  const handleEnter = (idx: number) => {
    if (isMobile) return;
    setHoveredIdx(idx);
    setPaused(true);
  };
  const handleLeave = () => {
    if (isMobile) return;
    setHoveredIdx(null);
    setPaused(false);
  };
  const handleTap = (idx: number) => {
    if (!isMobile) return;
    if (hoveredIdx === idx) { setHoveredIdx(null); setPaused(false); }
    else { setHoveredIdx(idx); setPaused(true); }
  };

  const renderSet = (keyPrefix: string, focusable: boolean) =>
    logos.map((logo, idx) => {
      const isActive = hoveredIdx === idx;
      return (
        <div
          key={`${keyPrefix}-${logo.name}`}
          onMouseEnter={() => handleEnter(idx)}
          onMouseLeave={handleLeave}
          onFocus={() => { setHoveredIdx(idx); setPaused(true); }}
          onBlur={() => { setHoveredIdx(null); setPaused(false); }}
          onClick={() => handleTap(idx)}
          tabIndex={focusable ? 0 : -1}
          role="img"
          aria-label={displayName(logo.name)}
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "6px",
            flexShrink: 0,
            padding: "8px 12px",
            cursor: "default",
            outline: "none",
          }}
        >
          <img
            src={logo.publicURL}
            alt={displayName(logo.name)}
            style={{
              height: 100,
              width: "auto",
              // maxWidth: 140,
              objectFit: "contain",
              filter: isActive
                ? "grayscale(0%) opacity(1)"
                : "grayscale(100%) opacity(0.5)",
              transition: "filter 0.25s ease",
              display: "block",
            }}
            loading="lazy"
          />
          <span
            style={{
              fontSize: "0.6rem",
              letterSpacing: "0.06em",
              textTransform: "uppercase",
              color: "#6b7280",
              whiteSpace: "nowrap",
              opacity: isActive ? 1 : 0,
              transform: isActive ? "translateY(0)" : "translateY(4px)",
              transition: "opacity 0.2s ease, transform 0.2s ease",
              pointerEvents: "none",
            }}
          >
            {displayName(logo.name)}
          </span>
        </div>
      );
    });

  return (
    <>
      <style>{`
        @keyframes cc-marquee {
          from { transform: translateX(0); }
          to   { transform: translateX(-50%); }
        }
      `}</style>
      <div
        style={{
          position: "relative",
          width: "100%",
          overflow: "hidden",
        }}
        aria-label="Client logos"
      >
        {/* Fade edges */}
        <div style={{
          position: "absolute", top: 0, left: 0, bottom: 0, width: 80, zIndex: 2,
          background: "linear-gradient(to right, var(--bg-base) 0%, transparent 100%)",
          pointerEvents: "none",
        }} />
        <div style={{
          position: "absolute", top: 0, right: 0, bottom: 0, width: 80, zIndex: 2,
          background: "linear-gradient(to left, var(--bg-base) 0%, transparent 100%)",
          pointerEvents: "none",
        }} />

        {/* Scrolling rail */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            flexWrap: "nowrap",
            alignItems: "center",
            gap: "2rem",
            width: "max-content",
            animation: "cc-marquee 30s linear infinite",
            animationPlayState: paused ? "paused" : "running",
          }}
        >
          {renderSet("a", true)}
          {renderSet("b", false)}
        </div>
      </div>
    </>
  );
};

export default LogoMarquee;
